export function resourceUrlFromServerUrl(e){const n="string"==typeof e?new URL(e):new URL(e.href);return n.hash="",n}export function checkResourceAllowed({requestedResource:e,configuredResource:n}){const t="string"==typeof e?new URL(e):new URL(e.href),r="string"==typeof n?new URL(n):new URL(n.href);if(t.origin!==r.origin)return!1;if(t.pathname.length<r.pathname.length)return!1;const h=t.pathname.endsWith("/")?t.pathname:t.pathname+"/",o=r.pathname.endsWith("/")?r.pathname:r.pathname+"/";return h.startsWith(o)}